      if (!parsedJson.tables || !Array.isArray(parsedJson.tables)) {
        showToast("Invalid JSON structure", "error");
        return;
      }
      const c_name = shopName;
      const salePromises = [];
      parsedJson.tables.forEach((table, tableIndex) => {
        const headers = tablesData[tableIndex][0];
        const counterTransferIndex = headers.findIndex((h) =>
          typeof h === "string" && h.toLowerCase().match(/cou\.?\s*trsfer|cou\s*ntrsfer|counter\s*transfer/i)
        );
        const rateIndex = headers.findIndex((h) => typeof h === "string" && h.toLowerCase().match(/rate/i));
        const outSaleIndex = headers.findIndex((h) =>
          typeof h === "string" && h.toLowerCase().match(/out\s*sale|sale/i)
        );
        const productIndex = headers.findIndex((h) =>
          typeof h === "string" && h.toLowerCase().match(/name\s*of\s*brands|product|item/i)
        );

        table.forEach((row, rowIndex) => {
          const validationValue = tablesData[tableIndex][rowIndex + 1][headers.length - 1];
          if (validationValue !== "Correct" && validationValue !== "Total: Correct") return;

          const productNameRaw =
            row["Name of Brands"] || row["name of brands"] || row.Product || row.product || row.Item || row.item ||
            (productIndex !== -1 ? tablesData[tableIndex][rowIndex + 1][productIndex] : null);
          const productName = typeof productNameRaw === "string" ? productNameRaw.trim() : productNameRaw;

          const rate = rateIndex !== -1 ? Number(tablesData[tableIndex][rowIndex + 1][rateIndex] || 0) : 0;
          const qty = outSaleIndex !== -1 ? Number(tablesData[tableIndex][rowIndex + 1][outSaleIndex] || 0) : 0;
          const counterTransfer = counterTransferIndex !== -1 ? Number(tablesData[tableIndex][rowIndex + 1][counterTransferIndex] || 0) : 0;

          if (
            productName && typeof productName === "string" && !productName.toLowerCase().includes("total") &&
            !isNaN(rate) && rate > 0 && !isNaN(qty) && qty > 0 && typeParam === "Godown"
          ) {
            const updatedProductName = cleanProductName(productName);
            const saleParams = new URLSearchParams({
              product_name: encodeURIComponent(updatedProductName),
              c_no: cNo,
              c_name: encodeURIComponent(c_name),
              p_name: encodeURIComponent(updatedProductName),
              date: currentDate,
              price: rate.toFixed(2),
              type: typeParam,
              qty: Number(qty),
              saleType: type,
            });
            const salesParams = decodeURIComponent(saleParams).replace(/%20/g, " ");
            const saleUrl = `https://deepikagroups.in/admin/api/add_AI_sale.php?${salesParams}`;
            salePromises.push(
              fetch(saleUrl, { method: "POST" })
                .then(async (response) => {
                  if (!response.ok) {
                    let errorMessage = await response.text();
                    try {
                      const errorData = JSON.parse(errorMessage);
                      errorMessage = errorData.message || errorMessage;
                    } catch (e) {}
                    throw new Error(`Failed to submit sale for ${productName}: ${errorMessage}`);
                  }
                  return { productName, success: true, type: "sale" };
                })
                .catch((err) => ({ productName, success: false, error: err.message, type: "sale" }))
            );
          }

          const sales = Number(tablesData[tableIndex][rowIndex + 1][outSaleIndex]);
          if (
            productName && !productName.toLowerCase().includes("total") &&
            !isNaN(sales) && sales > 0 && typeParam === "Counter"
          ) {
            const updatedProductName = cleanProductName(productName);
            const saleParams = new URLSearchParams({
              c_no: cNo,
              c_name: encodeURIComponent(c_name),
              p_name: encodeURIComponent(updatedProductName),
              date: currentDate,
              price: rate.toFixed(2),
              type: typeParam,
              qty: sales,
              saleType: type,
            });
            const salesParams = decodeURIComponent(saleParams).replace(/%20/g, " ");
            const saleUrl = `https://deepikagroups.in/admin/api/add_AI_sale.php?${salesParams}`;
            salePromises.push(
              fetch(saleUrl, { method: "POST" })
                .then(async (response) => {
                  if (!response.ok) {
                    let errorMessage = await response.text();
                    try {
                      const errorData = JSON.parse(errorMessage);
                      errorMessage = errorData.message || errorMessage;
                    } catch (e) {}
                    throw new Error(`Failed to submit sale for ${productName}: ${errorMessage}`);
                  }
                  return { productName, success: true, type: "sale" };
                })
                .catch((err) => ({ productName, success: false, error: err.message, type: "sale" }))
            );
          }

          if (typeParam === "Godown" && !isNaN(counterTransfer) && counterTransfer > 0) {
            const rateValue = Number(rate);
            const transferQty = Number(counterTransfer);
            const transferParams = new URLSearchParams({
              c_no: cNo,
              p_name: encodeURIComponent(productName),
              date: currentDate,
              price: rateValue.toFixed(2),
              qty: transferQty,
            });
            const transferParam = decodeURIComponent(transferParams).replace(/%20/g, " ");
            const transferUrl = `https://deepikagroups.in/admin/api/add_countTransfer.php?${transferParam}`;
            salePromises.push(
              fetch(transferUrl, { method: "POST" })
                .then(async (response) => {
                  if (!response.ok) {
                    let errorMessage = await response.text();
                    try {
                      const errorData = JSON.parse(errorMessage);
                      errorMessage = errorData.message || errorMessage;
                    } catch (e) {}
                    throw new Error(`Failed to submit counter transfer for ${productName}: ${errorMessage}`);
                  }
                  return { productName, success: true, type: "transfer" };
                })
                .catch((err) => ({ productName, success: false, error: err.message, type: "transfer" }))
            );
          }
        });
      });

      if (salePromises.length === 0) {
        showToast("No valid rows to submit. Ensure rows have valid product names, Rate, and Out Sale or Sale values or Counter Transfer values.", "warning");
        return;
      }

      setIsLoading(true);
      const results = await Promise.all(salePromises);
      setIsLoading(false);

      const successes = results.filter((r) => r.success);
      const failures = results.filter((r) => !r.success);

      if (successes.length > 0 && typeParam === "Godown") {
        const saleSuccesses = successes.filter((r) => r.type === "sale").length;
        const transferSuccesses = successes.filter((r) => r.type === "transfer").length;
        showToast(`Successfully submitted ${saleSuccesses} sale(s) + ${transferSuccesses} transfer(s)`, "success");
      }
      if (successes.length > 0 && typeParam === "Counter") {
        const saleSuccesses = successes.filter((r) => r.type === "sale").length;
        showToast(`Successfully submitted ${saleSuccesses} sale(s)`, "success");
      }
      if (failures.length > 0) {
        failures.forEach((f) => {
          showToast(`Failed to submit ${f.type} for ${f.productName}: ${f.error}`, "error");
        });
      }
    } catch (error) {
      console.error("Error submitting sales or transfers:", error);
      showToast(`Failed to submit data: ${error.message}`, "error");
      setIsLoading(false);
    }
  };

  const handleEditRow = async (tableIndex, rowIndex) => {
    try {
      const rowData = tablesData[tableIndex][rowIndex + 1];
      const initialEditValues = rowData.slice(0, rowData.length - 1).map((cell) =>
        cell !== null && cell !== undefined ? String(cell) : ""
      );
      const headers = tablesData[tableIndex][0];
      const productIndex = headers.findIndex((h) =>
        typeof h === "string" && h.toLowerCase().match(/name\s*of\s*brands|product|item/i)
      );
      let productInputSize = 10;
      if (productIndex !== -1 && initialEditValues[productIndex]) {
        productInputSize = Math.max(initialEditValues[productIndex].length * 2, 10);
      }
      setEditingRow({ tableIndex, rowIndex, productInputSize, productIndex });
      setEditValues(initialEditValues);
    } catch (err) {
      console.error("Error in handleEditRow:", err);
      showToast(`Failed to edit row: ${err.message}`, "error");
    }
  };

  const handleSaveEdit = async (tableIndex, rowIndex) => {
    try {
      const updatedTables = [...tablesData];
      const headers = updatedTables[tableIndex][0];
      const oldRow = [...updatedTables[tableIndex][rowIndex + 1]];
      const sanitizedEditValues = editValues.map((value, i) => {
        const header = headers[i].toLowerCase();
        if (header.match(/rate|amount|o\.b.*|ksbcl\s*receipt|cou\.?\s*.*|sale|total/i)) {
          if (value === "" || value === "-") return 0;
          if (!isNaN(parseFloat(value))) return parseFloat(value);
        }
        return String(value || "");
      });

      const productIndex = headers.findIndex((h) =>
        typeof h === "string" && h.toLowerCase().match(/name\s*of\s*brands|product|item/i)
      );
      const productName = productIndex !== -1 ? sanitizedEditValues[productIndex] : null;
      const isDuplicateProduct = typeof productName === "string" && productName.match(/^\s*\d+\s*$/);
      let validationValue = oldRow[headers.length - 1];

      if (productName && typeof productName === "string" && !productName.toLowerCase().includes("total")) {
        const stockResult = await fetchProductStockDetails(productName, tableIndex, rowIndex);
        const validations = [];
        const amountIndex = headers.findIndex((h) => h.toLowerCase() === "amount");
        const rateIndex = headers.findIndex((h) => h.toLowerCase() === "rate");
        const outSaleIndex = headers.findIndex((h) =>
          h.toLowerCase().match(/out\s*sale|sale/i)
        );
        const obIndex = headers.findIndex((h) =>
          h.toLowerCase().match(/o\.b\.?|о\.b\.?/i)
        );
        const ksbclIndex = headers.findIndex((h) =>
          h.toLowerCase().match(/ksbcl\s*receipt|receipt|ksbol\s*receipt/i)
        );
        const counterTransferIndex = headers.findIndex((h) =>
          h.toLowerCase().match(/cou\.?\s*trsfer|cou\s*ntrsfer|counter\s*transfer/i)
        );
        const totalIndex = headers.findIndex((h) => h.toLowerCase() === "total");

        if (stockResult?.error) {
          validations.push(`Stock Error: ${stockResult.error}`);
        } else if (!isDuplicateProduct) {
          if (obIndex !== -1 && stockResult?.data) {
            const obValue = Number(sanitizedEditValues[obIndex]);
            if (isNaN(obValue)) {
              validations.push(`Invalid Opening Balance: "${sanitizedEditValues[obIndex]}" is not a valid number`);
            } else if (obValue !== stockResult.data.OpeningStock) {
              validations.push(`OB Mismatch: Expected ${obValue}, got ${stockResult.data.OpeningStock}`);
            }
          } else if (!isDuplicateProduct && obIndex !== -1 && !stockResult?.data) {
            validations.push("Opening Balance: No stock data available");
          }

          if (typeParam === "Counter") {
            if (ksbclIndex !== -1 && stockResult?.data?.CounterReceived !== undefined) {
              const receiptValue = Number(sanitizedEditValues[ksbclIndex]);
              if (isNaN(receiptValue)) {
                validations.push(`Invalid Receipt: "${sanitizedEditValues[ksbclIndex]}" is not a valid number`);
              } else if (receiptValue !== stockResult.data.CounterReceived) {
                validations.push(`Receipt Mismatch: Expected ${receiptValue}, got ${stockResult.data.CounterReceived}`);
              }
            } else if (!isDuplicateProduct && ksbclIndex !== -1 && !stockResult?.data) {
              validations.push("Receipt: No stock data available");
            }

            if (outSaleIndex !== -1 && stockResult?.data?.Sales !== undefined && stockResult.data.Sales > 0) {
              const saleValue = Number(sanitizedEditValues[outSaleIndex]);
              if (isNaN(saleValue)) {
                validations.push(`Invalid Sale: "${sanitizedEditValues[outSaleIndex]}" is not a valid number`);
              } else if (saleValue !== stockResult.data.Sales) {
                validations.push(`Sale Mismatch: Expected ${saleValue}, got ${stockResult.data.Sales}`);
              }
            } else if (!isDuplicateProduct && outSaleIndex !== -1 && !stockResult?.data) {
              validations.push("Sale: No stock data available");
            }

            if (rateIndex !== -1 && totalIndex !== -1 && amountIndex !== -1 && stockResult?.data) {
              const rateValue = Number(sanitizedEditValues[rateIndex]);
              const cbValue = Number(sanitizedEditValues[totalIndex]) - Number(sanitizedEditValues[outSaleIndex]);
              const actualAmount = Number(sanitizedEditValues[amountIndex]);
              const expectedAmount = stockResult.data.Price * Number(sanitizedEditValues[outSaleIndex]);

              if (isNaN(rateValue)) {
                validations.push(`Invalid Rate: "${sanitizedEditValues[rateIndex]}" is not a valid number`);
              } else if (rateValue !== stockResult.data.Price) {
                validations.push(`Rate Mismatch: Expected ${rateValue}, got ${stockResult.data.Price}`);
              }
              if (isNaN(cbValue)) {
                validations.push(`Invalid Closing Balance: "${sanitizedEditValues[totalIndex]}" is not a valid number`);
              }
              if (isNaN(actualAmount)) {
                validations.push(`Invalid Amount: "${sanitizedEditValues[amountIndex]}" is not a valid number`);
              } else if (Math.abs(actualAmount - expectedAmount) > 0.01) {
                validations.push(`Amount Mismatch: Expected ${expectedAmount.toFixed(2)}, got ${actualAmount}`);
              }
            }
          } else {
            if (ksbclIndex !== -1 && stockResult?.data?.Purchase !== undefined) {
              const ksbclValue = Number(sanitizedEditValues[ksbclIndex]);
              if (isNaN(ksbclValue)) {
                validations.push(`Invalid KSBCL Receipt: "${sanitizedEditValues[ksbclIndex]}" is not a valid number`);
              } else if (ksbclValue !== stockResult.data.Purchase) {
                validations.push(`KSBCL Receipt Mismatch: Expected ${ksbclValue}, got ${stockResult.data.Purchase}`);
              }
            } else if (!isDuplicateProduct && ksbclIndex !== -1 && !stockResult?.data) {
              validations.push("KSBCL Receipt: No stock data available");
            }

            if (counterTransferIndex !== -1 && stockResult?.data?.Counter_Transfer !== undefined) {
              const counterTransferValue = Number(sanitizedEditValues[counterTransferIndex]);
              if (isNaN(counterTransferValue)) {
                validations.push(`Invalid Counter Transfer: "${sanitizedEditValues[counterTransferIndex]}" is not a valid number`);
              } else if (
                counterTransferValue !== stockResult.data.Counter_Transfer &&
                stockResult.data.Counter_Transfer > 0 &&
                stockResult.data.Counter_Transfer !== null
              ) {
                validations.push(
                  `Counter Transfer Mismatch: Expected ${counterTransferValue}, got ${stockResult.data.Counter_Transfer}`
                );
              }
            } else if (!isDuplicateProduct && counterTransferIndex !== -1 && !stockResult?.data) {
              validations.push("Counter Transfer: No stock data available");
            }

            if (rateIndex !== -1 && outSaleIndex !== -1 && amountIndex !== -1) {
              const rateValue = Number(sanitizedEditValues[rateIndex]);
              const saleValue = Number(sanitizedEditValues[outSaleIndex]);
              const actualAmount = Number(sanitizedEditValues[amountIndex]);
              if (isNaN(actualAmount)) {
                validations.push(`Invalid Amount: "${sanitizedEditValues[amountIndex]}" is not a valid number`);
              } else if (!isNaN(rateValue) && !isNaN(saleValue)) {
                const closeBalance = stockResult?.data?.ClosingStock || 0;
                let calculatedAmount = 0;
                if (closeBalance > 0) {
                  calculatedAmount = (saleValue / closeBalance) * rateValue;
                }
                if (Math.abs(actualAmount - calculatedAmount) > 0.01) {
                  validations.push(
                    `Amount Mismatch: Expected ${calculatedAmount.toFixed(2)}, got ${actualAmount}`
                  );
                }
              }
            }
          }

          if (stockResult?.error === "Product does not exist") {
            validations.length = 0;
            validations.push("Error: Product name spelling is incorrect");
          }
          validationValue = validations.length > 0 ? validations.join("; ") : "Correct";

          const updatedStockResults = [...stockResultsState];
          const existingResultIndex = updatedStockResults.findIndex(
            (r) => r.tableIndex === tableIndex && r.rowIndex === rowIndex
          );
          if (existingResultIndex !== -1) {
            updatedStockResults[existingResultIndex] = stockResult;
          } else {
            updatedStockResults.push(stockResult);
          }
          setStockResultsState(updatedStockResults);

          const newStockDetails = { ...stockDetails };
          if (!stockResult?.error) {
            newStockDetails[`${tableIndex}-${rowIndex}`] = stockResult.data;
          }
          setStockDetails(newStockDetails);
        }

        const nonProductColumns = sanitizedEditValues
          .slice(0, sanitizedEditValues.length - 1)
          .filter((_, index) => index !== productIndex);
        const allZeros = nonProductColumns.every(
          (cell) => cell === "0" || cell === null || cell === undefined || cell === ""
        );

        if (allZeros && !validationValue.toLowerCase().includes("total")) {
          updatedTables[tableIndex].splice(rowIndex + 1, 1);
          showToast("Row removed as all values are zero", "success");
        } else {
          updatedTables[tableIndex][rowIndex + 1] = [...sanitizedEditValues, validationValue];
        }

        const amountIdx = headers.findIndex((h) => h.toLowerCase() === "amount");
        let tableTotal = 0;
        const updatedAmounts = amounts.filter((a) => !(a.tableIndex === tableIndex && a.rowIndex === rowIndex + 1));
        if (amountIdx !== -1 && !allZeros) {
          const amount = Number(sanitizedEditValues[amountIdx]);
          if (!isNaN(amount) && amount >= 0) {
            updatedAmounts.push({ tableIndex, rowIndex: rowIndex + 1, amount });
            tableTotal = updatedAmounts
              .filter((a) => a.tableIndex === tableIndex)
              .reduce((sum, a) => sum + a.amount, 0);
          }
        }

        const lastRow = updatedTables[tableIndex][updatedTables[tableIndex].length - 1];
        if (
          lastRow && lastRow[0] &&
          (lastRow[0].toLowerCase().includes("total") || lastRow[0].toLowerCase().includes("grand total")) &&
          amountIdx !== -1
        ) {
          const totalAmount = Number(lastRow[amountIdx]);
          lastRow[headers.length - 1] = isNaN(totalAmount)
            ? `Total: invalid number (${lastRow[amountIdx]})`
            : Math.abs(totalAmount - tableTotal) > 0.01
            ? `Total Mismatch: ${totalAmount} != ${tableTotal}`
            : `Total: ${tableTotal}`;
        }

        setTablesData(updatedTables);
        setAmounts(updatedAmounts);
        setEditingRow(null);
        setEditValues([]);

        const tableJSON = convertTableToJSON(updatedTables, stockResultsState, true);
        setJsonOutput(JSON.stringify(tableJSON, null, 2));

        if (!allZeros) {
          showToast("Row updated successfully!", "success");
        }
      }
    } catch (error) {
      console.error("Error in handleSaveEdit:", error);
      showToast(`Failed to save edit: ${error.message}`, "error");
    }
  };

  const handleDeleteRow = async (tableIndex, rowIndex) => {
    try {
      const updatedTables = [...tablesData];
      const headers = updatedTables[tableIndex][0];
      updatedTables[tableIndex].splice(rowIndex + 1, 1);
      const updatedAmounts = amounts.filter((a) => !(a.tableIndex === tableIndex && a.rowIndex === rowIndex + 1));

      if (updatedTables[tableIndex].length > 1) {
        const lastRow = updatedTables[tableIndex][updatedTables[tableIndex].length - 1];
        if (
          lastRow[0] && (lastRow[0].toLowerCase().includes("total") || lastRow[0].toLowerCase().includes("grand total"))
        ) {
          const amountIndex = headers.findIndex((h) => h.toLowerCase() === "amount");
          const tableTotal = updatedAmounts
            .filter((a) => a.tableIndex === tableIndex)
            .reduce((sum, a) => sum + a.amount, 0);
          const totalAmount = Number(lastRow[amountIndex]);
          lastRow[headers.length - 1] = isNaN(totalAmount)
            ? `Total: invalid number (${lastRow[amountIndex]})`
            : Math.abs(totalAmount - tableTotal) > 0.01
            ? `Total Mismatch: ${totalAmount} != ${tableTotal}`
            : `Total: ${tableTotal}`;
        }
      }

      setTablesData(updatedTables);
      setAmounts(updatedAmounts);
      const tableJSON = convertTableToJSON(updatedTables, stockResultsState, true);
      setJsonOutput(JSON.stringify(tableJSON, null, 2));
      showToast("Row deleted successfully!", "success");
    } catch (err) {
      console.error("Error deleting row:", err);
      showToast(`Failed to delete row: ${err.message}`, "error");
    }
  };

  const syntaxHighlight = (json) => {
    if (!json) return json;
    json = json.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
    return json.replace(
      /("(\\u[a-zA-Z0-9]{4}|\\[^u]|[^\\"])*"(\s*:)?|\b(true|false|null)\b|-?\d+(?:\.\d*)?(?:[eE][+\-]?\d+)?)/g,
      (match) => {
        let cls = "json-number";
        if (/^"/.test(match)) {
          cls = /:/.test(match) ? "json-key" : "json-string";
        } else if (/true|false/.test(match)) {
          cls = "json-boolean";
        } else if (/null/.test(match)) {
          cls = "json-null";
        }
        return `<span class="${cls}">${match}</span>`;
      }
    );
  };

  useEffect(() => {
    if (tablesData.length > 0 && tablesData[0].length > 0) {
      const tableJSON = convertTableToJSON(tablesData, stockResultsState, true);
      setJsonOutput(JSON.stringify(tableJSON, null, 2));
    }
  }, [tablesData, stockResultsState]);

  return (
    <div className="App">
      {toast.show && (
        <div className={`alert alert-${toast.type}`}>
          <svg
            xmlns="http://www.w3.org/2000/svg"
            className="icon"
            width="24"
            height="24"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            {toast.type === "success" && (
              <>
                <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path>
                <polyline points="22 4 12 14.01 9 11.01"></polyline>
              </>
            )}
            {toast.type === "error" && (
              <>
                <circle cx="12" cy="12" r="10"></circle>
                <line x1="12" y1="16" x2="12" y2="12"></line>
                <line x1="12" y1="8" x2="12.01" y2="8"></line>
              </>
            )}
            {toast.type === "warning" && (
              <>
                <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"></path>
                <line x1="12" y1="9" x2="12" y2="13"></line>
                <line x1="12" y1="17" x2="12.01" y2="17"></line>
              </>
            )}
          </svg>
          <span className="alert-message">{toast.message}</span>
          <button className="ml-auto" onClick={closeToast}>
            <svg
              xmlns="http://www.w3.org/2000/svg"
              width="24"
              height="24"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <line x1="18" y1="6" x2="6" y2="18"></line>
              <line x1="6" y1="6" x2="18" y2="18"></line>
            </svg>
          </button>
        </div>
      )}

      <nav className="navbar">
        <div className="container">
          <div className="items flex-row">
            {numberCounter === "2" && (
              <select
                value={type}
                onChange={(e) => setType(e.target.value)}
                className="form-control"
              >
                <option value="" disabled>Select type</option>
                <option value="Counter">Counter</option>
                <option value="Godown">Godown</option>
              </select>
            )}
            <div className="date">
              <input
                type="date"
                value={currentDate}
                onChange={(e) => setCurrentDate(e.target.value)}
                className="form-control"
              />
            </div>
            <div className="upload-section">
              <input
                id="file-upload"
                type="file"
                accept="image/*"
                capture="environment"
                onChange={handleFileChange}
                disabled={!cNo}
                className="hidden"
              />
              <label htmlFor="file-upload" className="btn btn-primary">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  width="24"
                  height="24"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect>
                  <circle cx="8.5" cy="8.5" r="1.5"></circle>
                  <polyline points="21 15 16 10 5 21"></polyline>
                </svg>
                Upload or capture image
              </label>
            </div>
          </div>
          {isLoading && (
            <div className="progress-container">
              <div className="progress-bar">
                <div className="progress-fill" style={{ width: `${progress}%` }}></div>
              </div>
              <div className="progress-text">Processing image... {Math.round(progress)}%</div>
            </div>
          )}
          {error && (
            <div className="alert alert-danger">
              <svg
                xmlns="http://www.w3.org/2000/svg"
                width="24"
                height="24"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <circle cx="12" cy="12" r="10"></circle>
                <line x1="12" y1="16" x2="12" y2="12"></line>
                <line x1="12" y1="8" x2="12.01" y2="8"></line>
              </svg>
              {error}
            </div>
          )}
        </div>
      </nav>

      {image && (
        <div className="card fade-in">
          <h2 className="section-title">Image preview</h2>
          <div className="image-preview-container">
            <img src={image} alt="Uploaded image" className="img-fluid" />
          </div>
        </div>
      )}

      {tablesData.length > 0 && tablesData[0].length > 0 && (
        <div className="card fade-in">
          <div className="card-header">
            <h2 className="section-title">Extracted data tables</h2>
          </div>
          <div className="tables-container">
            {tablesData.map((table, tableIndex) => (
              <div key={`table-${tableIndex}`} className="table-wrapper">
                <h3 className="table-title">Table {tableIndex + 1}</h3>
                <div className="table-responsive">
                  <table className="table table-bordered">
                    <thead>
                      <tr>
                        {table[0].map((header, index) => (
                          <th key={`header-${tableIndex}-${index}`}>
                            {header || `Column ${index + 1}`}
                          </th>
                        ))}
                        <th>Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {(() => {
                        const dataRows = table.slice(1).map((row, index) => ({ row, index }));
                        const correctRows = dataRows.filter(
                          (r) => r.row[table[0].length - 1] === "Correct" || r.row[table[0].length - 1] === "Total: Correct"
                        );
                        const errorRows = dataRows.filter(
                          (r) => r.row[table[0].length - 1] !== "Correct" && r.row[table[0].length - 1] !== "Total: Correct"
                        );
                        const sortedRows = [...correctRows, ...errorRows];

                        return sortedRows.map((rowObj) => {
                          const rowData = rowObj.row;
                          const originalIndex = rowObj.index;
                          const validationValue = rowData[table[0].length - 1];
                          const hasError = validationValue !== "Correct" && validationValue !== "Total: Correct";
                          const isEditing = editingRow &&
                            editingRow.tableIndex === tableIndex &&
                            editingRow.rowIndex === originalIndex;

                          return (
                            <tr key={`row-${tableIndex}-${originalIndex}`} className={hasError ? "table-danger" : ""}>
                              {isEditing
                                ? rowData.slice(0, rowData.length - 1).map((_, colIndex) => (
                                    <td key={`edit-cell-${tableIndex}-${originalIndex}-${colIndex}`}>
                                      <input
                                        type="text"
                                        value={editValues[colIndex] || ""}
                                        onChange={(e) => {
                                          const newEditValues = [...editValues];
                                          newEditValues[colIndex] = e.target.value;
                                          setEditValues(newEditValues);
                                        }}
                                        size={
                                          editingRow.productIndex === colIndex
                                            ? editingRow.productInputSize
                                            : 4
                                        }
                                        className="form-control"
                                      />
                                    </td>
                                  ))
                                : rowData.map((cell, colIndex) => (
                                    <td key={`cell-${tableIndex}-${originalIndex}-${colIndex}`}>
                                      {colIndex === table[0].length - 1 && cell !== "Correct" && cell !== "" ? (
                                        <OverlayTrigger
                                          placement="top"
                                          show={visibleTooltip === `${tableIndex}-${originalIndex}`}
                                          overlay={<Tooltip>{cell}</Tooltip>}
                                        >
                                          <span
                                            className="text-danger"
                                            onClick={() =>
                                              setVisibleTooltip(
                                                visibleTooltip === `${tableIndex}-${originalIndex}`
                                                  ? ""
                                                  : `${tableIndex}-${originalIndex}`
                                              )
                                            }
                                          >
                                            {cell.substring(0, 20)}
                                            {cell.length > 20 ? "..." : ""}
                                          </span>
                                        </OverlayTrigger>
                                      ) : (
                                        cell
                                      )}
                                    </td>
                                  ))}
                              <td>
                                {isEditing ? (
                                  <Button
                                    variant="success"
                                    size="sm"
                                    onClick={() => handleSaveEdit(tableIndex, originalIndex)}
                                  >
                                    <Save />
                                  </Button>
                                ) : (
                                  <>
                                    <Button
                                      variant="primary"
                                      size="sm"
                                      onClick={() => handleEditRow(tableIndex, originalIndex)}
                                      className="mr-1"
                                    >
                                      <PencilSquare />
                                    </Button>
                                    <Button
                                      variant="danger"
                                      size="sm"
                                      onClick={() => handleDeleteRow(tableIndex, originalIndex)}
                                    >
                                      <Trash />
                                    </Button>
                                  </>
                                )}
                              </td>
                            </tr>
                          );
                        });
                      })()}
                    </tbody>
                  </table>
                </div>
              </div>
            ))}
            <div className="action-buttons">
              <Button variant="primary" onClick={handleDownloadJSON} disabled={!jsonOutput}>
                Download JSON
              </Button>
              <Button variant="success" onClick={handleSaveJSON} disabled={!jsonOutput}>
                Save JSON
              </Button>
              <Button variant="info" onClick={handleSubmitSales} disabled={!jsonOutput || isLoading}>
                {isLoading ? "Submitting..." : "Submit Sales"}
              </Button>
            </div>
          </div>
        </div>
      )}

      {jsonOutput && (
        <div className="card fade-in">
          <h2 className="section-title">JSON Output</h2>
          <pre
            className="json-output"
            dangerouslySetInnerHTML={{ __html: syntaxHighlight(jsonOutput) }}
          ></pre>
        </div>
      )}
    </div>
  );
}

export default Camera;
